  try {
    const setClauses = [];
    const values = [];
    let paramIndex = 1;
    if (updates.name) {
      setClauses.push(`name = $${paramIndex++}`);
      values.push(updates.name);
    }
    if (updates.scopes) {
      setClauses.push(`scopes = $${paramIndex++}`);
      values.push(JSON.stringify(updates.scopes));
    }
    values.push(keyId);
    values.push(userId);
    const result = await query(
      `UPDATE api_keys
       SET ${setClauses.join(", ")}
       WHERE id = $${paramIndex++} AND user_id = $${paramIndex}
       RETURNING id, name, key_prefix, scopes, last_used_at, created_at, expires_at, is_active`,
      values
    );
    if (result.rows.length > 0) {
      data = result.rows[0];
    }
  } catch (err) {
    console.error("[Users] RDS update API key error:", err);
    if (supabaseAvailable4 && getSupabaseAdmin5) {
      try {
        const admin = getSupabaseAdmin5();
        const { data: sbData, error: error46 } = await admin.from("api_keys").update(updates).eq("id", keyId).eq("user_id", userId).select("id, name, key_prefix, scopes, last_used_at, created_at, expires_at, is_active").single();
        if (error46) {
          throw error46;
        }
        data = sbData;
      } catch (sbErr) {
        console.error("[Users] Supabase update API key error:", sbErr);
      }
    }
  }
  if (!data) {
    throw Errors.notFound("API key", keyId);
  }
